{
const {MODULES,CODE,GLOSSARY,PROJECTS,REFERENCES,DOCS}=window.COURSE;
const $=(s,e=document)=>e.querySelector(s), $$=(s,e=document)=>[...e.querySelectorAll(s)];
const state={completed:new Set(JSON.parse(localStorage.getItem('dsf-completed')||'[]')),bookmarks:new Set(JSON.parse(localStorage.getItem('dsf-bookmarks')||'[]')),scores:JSON.parse(localStorage.getItem('dsf-scores')||'{}'),theme:localStorage.getItem('dsf-theme')||'dark'};
document.documentElement.dataset.theme=state.theme;
const allLessons=MODULES.flatMap(m=>m.lessons.map(l=>({...l,module:m})));
const save=()=>{localStorage.setItem('dsf-completed',JSON.stringify([...state.completed]));localStorage.setItem('dsf-bookmarks',JSON.stringify([...state.bookmarks]));localStorage.setItem('dsf-scores',JSON.stringify(state.scores));};
const pct=()=>Math.round(state.completed.size/allLessons.length*100);
function toast(msg){const el=$('#toast');el.textContent=msg;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),1800)}
function icon(name){return ({menu:'â˜°',sun:'â—',check:'âœ“',bookmark:'â—‡',search:'âŒ•',arrow:'â†’'}[name]||'Â·')}
function shell(content,active=''){return `<div class="shell"><header class="topbar"><button class="icon-btn mobile-menu" aria-label="Toggle curriculum">${icon('menu')}</button><a class="brand" href="#/"><span class="mark">DS</span><span>Distributed Systems Fieldbook</span></a><nav class="topnav" aria-label="Primary"><a class="${active==='curriculum'?'active':''}" href="#/curriculum">Curriculum</a><a class="${active==='lab'?'active':''}" href="#/lab">Architecture Lab</a><a class="${active==='projects'?'active':''}" href="#/projects">Projects</a><a class="${active==='reference'?'active':''}" href="#/reference">Reference</a></nav><div class="top-actions"><a class="icon-btn hide-mobile" href="#/dashboard" aria-label="Progress dashboard">${pct()}%</a><button id="theme" class="icon-btn" aria-label="Toggle color theme">${icon('sun')}</button></div></header><div class="layout">${sidebar(active)}<main id="main">${content}</main></div><div id="toast" class="toast" role="status" aria-live="polite"></div></div>`}
function sidebar(active){return `<aside class="sidebar" aria-label="Course modules"><div class="side-progress"><div class="side-label">Course progress Â· ${state.completed.size}/${allLessons.length}</div><div class="meter"><span style="width:${pct()}%"></span></div></div><div class="side-links"><a class="${active==='home'?'active':''}" href="#/"><span class="side-dot"></span>Overview</a>${MODULES.map(m=>`<a class="${m.lessons.every(l=>state.completed.has(l.id))?'done':''}" href="#/lesson/${m.lessons[0].id}" title="${m.title}"><span class="side-dot"></span>${String(m.id).padStart(2,'0')} Â· ${m.title}</a>`).join('')}</div></aside>`}
function layout(page,active){$('#app').innerHTML=shell(`<div class="page">${page}<footer class="footer"><span>Distributed Systems Fieldbook Â· verified 14 Oct 2026</span><span>Progress stays in this browser.</span></footer></div>`,active);bindGlobal()}
function bindGlobal(){
  $('#theme')?.addEventListener('click',()=>{state.theme=state.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=state.theme;localStorage.setItem('dsf-theme',state.theme)});
  $('.mobile-menu')?.addEventListener('click',()=>$('.sidebar').classList.toggle('open'));
  $$('.copy').forEach(b=>b.onclick=async()=>{await navigator.clipboard.writeText(b.closest('.code-wrap').querySelector('code').innerText);toast('Copied to clipboard')});
}
function home(){const next=allLessons.find(l=>!state.completed.has(l.id))||allLessons[0];layout(`<section class="hero"><div><div class="eyebrow">Go Â· distributed systems Â· production operations</div><h1>Engineer systems that survive <em>reality.</em></h1><p class="lede">A field guide from your first HTTP handler to operating distributed commerce under partial failure. Read the theory, inspect the code, run the lab, and defend the trade-offs.</p><div class="hero-actions"><a class="btn primary" href="#/lesson/${next.id}">${state.completed.size?'Continue learning':'Start the course'} ${icon('arrow')}</a><a class="btn ghost" href="#/curriculum">Explore curriculum</a></div></div><div class="terminal" aria-label="Course stack preview"><div class="term-top"><i></i><i></i><i></i></div><div><span class="term-cyan">$</span> go test -race ./...</div><div class="term-green">âœ“</div><div><span class="term-cyan">$</span> kubectl rollout status deploy/order</div><div class="term-green">deployment successfully rolled out</div><div><span class="term-cyan">$</span> curl /ready</div><div>{ "status": "ready", "checks": 4 }</div></div></section><section class="stats"><div class="stat"><strong>30</strong><span>Production-focused modules</span></div><div class="stat"><strong>${allLessons.length}</strong><span>Lessons & laboratories</span></div><div class="stat"><strong>3</strong><span>Portfolio projects</span></div><div class="stat"><strong>~${MODULES.reduce((n,m)=>n+m.hours,0)}h</strong><span>Guided study</span></div></section>${section('A deliberate learning path','Concepts build from request mechanics to architecture judgment.',MODULES.filter(m=>[1,7,12,19,29,30].includes(m.id)).map(moduleCard).join(''))}${section('What you will build','Projects progress from a bounded service to a fully instrumented commerce platform.',PROJECTS.map(projectCard).join(''))}`, 'home')}
function section(kicker,title,body){return `<section><div class="section-head"><div><div class="eyebrow">${kicker}</div><h2>${title}</h2></div></div><div class="grid">${body}</div></section>`}
function moduleCard(m){return `<article class="card"><div class="meta"><span class="badge ${m.level}">${m.level}</span><span>${m.hours} hours</span></div><h3>${String(m.id).padStart(2,'0')} Â· ${m.title}</h3><p>${m.summary}</p><a class="card-link" href="#/lesson/${m.lessons[0].id}" aria-label="Open ${m.title}"></a></article>`}
function projectCard(p,i){return `<article class="card project-card"><div class="meta"><span class="badge ${p.level}">${p.level}</span><span>${p.weeks}</span></div><h3>${p.title}</h3><p>${p.desc}</p>${i===undefined?'':`<a class="card-link" href="#/projects" aria-label="View projects"></a>`}</article>`}
function curriculum(){layout(`<div class="eyebrow">Structured path</div><h1 class="page-title">Curriculum explorer</h1><p class="lede">Search all ${allLessons.length} lessons. Each module ends with a lab, assessment, and explicit production trade-offs.</p><div class="curriculum-toolbar"><input id="search" class="search" type="search" placeholder="Search modules, topics, lessonsâ€¦" aria-label="Search curriculum"><button class="filter active" data-level="All">All</button>${['Beginner','Intermediate','Advanced','Expert'].map(x=>`<button class="filter" data-level="${x}">${x}</button>`).join('')}</div><div id="module-list" class="module-list">${MODULES.map(moduleRow).join('')}</div>`,'curriculum');let level='All';const render=()=>{const q=$('#search').value.toLowerCase();const list=MODULES.filter(m=>(level==='All'||m.level===level)&&[m.title,m.summary,...m.topics,...m.lessons.map(l=>l.title)].join(' ').toLowerCase().includes(q));$('#module-list').innerHTML=list.length?list.map(moduleRow).join(''):`<div class="empty">No lessons match that search.</div>`;bindRows()};$('#search').oninput=render;$$('.filter').forEach(b=>b.onclick=()=>{$$('.filter').forEach(x=>x.classList.remove('active'));b.classList.add('active');level=b.dataset.level;render()});bindRows()}
function moduleRow(m){const done=m.lessons.filter(l=>state.completed.has(l.id)).length;return `<article class="module-row"><button class="module-head" aria-expanded="false"><span class="module-num">M${String(m.id).padStart(2,'0')}</span><span><h3>${m.title}</h3><span class="meta"><span class="badge ${m.level}">${m.level}</span><span>${m.lessons.length} lessons Â· ${m.hours}h Â· ${done}/${m.lessons.length} complete</span></span></span><span>ï¼‹</span></button><div class="module-body"><p>${m.summary}</p>${m.lessons.map(l=>`<a class="lesson-link" href="#/lesson/${l.id}"><span>${state.completed.has(l.id)?'âœ“ ':''}${l.title}</span><span>${l.duration} min â†’</span></a>`).join('')}</div></article>`}
function bindRows(){$$('.module-head').forEach(b=>b.onclick=()=>{const row=b.closest('.module-row');row.classList.toggle('open');b.setAttribute('aria-expanded',row.classList.contains('open'))})}
function esc(s){return s.replace(/[&<>]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[c]))}
function codeBlock(ex){return `<div class="code-wrap"><div class="code-head"><span>${ex.label} Â· ${ex.lang}</span><button class="copy">Copy</button></div><pre><code>${esc(ex.code)}</code></pre></div>`}
function lesson(id){const x=allLessons.find(l=>l.id===id);if(!x)return notFound();const m=x.module,idx=allLessons.findIndex(l=>l.id===id),ex=CODE[m.id]||CODE[2];const q=quizFor(m);layout(`<div class="lesson-shell"><article class="prose"><header class="lesson-head"><div class="meta"><span class="badge ${m.level}">${m.level}</span><span>Module ${m.id} Â· Lesson ${m.lessons.indexOf(m.lessons.find(l=>l.id===id))+1}</span><span>${x.duration} minutes</span></div><h1>${x.title}</h1><p class="lede">${m.summary}</p><div class="lesson-actions"><button id="complete" class="btn ${state.completed.has(id)?'primary':'ghost'}">${state.completed.has(id)?'âœ“ Completed':'Mark complete'}</button><button id="bookmark" class="btn ghost bookmark ${state.bookmarks.has(id)?'on':''}">${state.bookmarks.has(id)?'â—† Bookmarked':'â—‡ Bookmark'}</button></div></header><section id="objectives"><h2>What you will learn</h2><div class="objective-list">${m.topics.slice(0,4).map(t=>`<div class="objective">${t}</div>`).join('')}</div><p><strong>Prerequisites:</strong> ${m.id===1?'None beyond basic programming.':`Module ${Math.max(1,m.id-1)} or equivalent experience.`} You should be able to read Go and run shell commands.</p></section><section id="concept"><h2>Concept and mechanics</h2><p>${m.summary} The engineering goal is not to memorize a product feature. It is to identify the invariant, the failure boundary, and the observable evidence that tells you whether the design still holds.</p><p>Start by naming the owner of each state transition. Then ask which facts must be immediately consistent, which can converge, and what a retry means after the caller loses the response. Alternative designs trade operational simplicity, coupling, latency, and recovery behavior; there is no universally correct topology.</p><div class="callout"><strong>Core production lesson</strong>${m.failure}</div><h3>Topics in this lesson</h3><ul>${m.topics.map(t=>`<li>${t}: define its boundary, mechanism, and measurable failure mode.</li>`).join('')}</ul></section><section id="architecture"><h2>Architecture</h2><div class="diagram"><div class="flow"><div class="node">Client</div><span class="arrow">â†’ request â†’</span><div class="node">${m.title.split(' ').slice(0,2).join(' ')} service</div><span class="arrow">â†’</span><div class="node data">Owned state</div><span class="arrow">â†’ event â†’</span><div class="node event">Downstream</div></div></div><p>The solid request path has a bounded deadline. The event path carries an immutable fact with an identifier, schema version, and causation metadata. On failure, callers preserve their own invariant and reconcile instead of guessing remote state.</p></section><section id="implementation"><h2>Go implementation</h2><p>This example is labeled honestly. Add domain-specific validation, authorization, telemetry, and operational configuration before treating it as deployable.</p>${codeBlock(ex)}<h3>Important lines</h3><ul><li><code>context.Context</code> carries cancellation across the call boundary; do not store it in a struct.</li><li>Errors retain cause with <code>%w</code> so policy can distinguish timeouts, conflicts, and permanent failures.</li><li>Concurrency and I/O are bounded; cleanup has an explicit owner.</li></ul></section><section id="run"><h2>Run and verify</h2><div class="code-wrap"><div class="code-head"><span>shell Â· local workflow</span><button class="copy">Copy</button></div><pre><code>mkdir fieldbook-lab &amp;&amp; cd fieldbook-lab\ngo mod init example.com/fieldbook-lab\n# save the example as main.go\ngo fmt ./...\ngo test -race ./...\ngo run .\n# in another terminal\ncurl -i http://localhost:8080/health</code></pre></div><p><strong>Expected:</strong> tests exit zero, the race detector reports no race, and the health endpoint returns a successful status. Stop with Ctrl+C and verify that in-flight work receives a bounded shutdown window.</p></section><section id="failure"><h2>Failure scenarios</h2><ul class="checklist"><li><strong>Dependency timeout:</strong> inspect latency by dependency, cancellation errors, and saturation. Do not retry beyond the request budget.</li><li><strong>Duplicate delivery:</strong> identify the business key and prove the handlerâ€™s durable deduplication boundary.</li><li><strong>Resource exhaustion:</strong> inspect queue depth, goroutines, pool wait time, file descriptors, and memoryâ€”not CPU alone.</li></ul></section><section id="tradeoffs"><h2>Best practices and trade-offs</h2><p>Prefer the simplest topology that satisfies the invariant. Security controls belong at every trust boundary; observability must avoid secrets and unbounded cardinality. Measure before optimizing, and record why a more complex approach was rejected.</p><div class="callout"><strong>When this technique is inappropriate</strong>Do not distribute a module unless independent ownership, scaling, isolation, or release cadence repays the network and operational cost.</div></section><section id="practice"><h2>Practice</h2><ol><li>Draw the normal path and annotate every timeout and owner.</li><li>Inject the failure described above and list the signals that reveal it.</li><li>Write an ADR comparing this design with a simpler in-process alternative.</li></ol><h3>Practical challenge</h3><p>${m.lab}</p><p><strong>Acceptance criteria:</strong> automated tests cover success and failure; every external call is bounded; duplicate work is safe; telemetry connects the request to its downstream effects; the README names remaining assumptions.</p></section><section id="quiz"><h2>Knowledge check</h2>${q.map((item,i)=>quizHTML(item,i)).join('')}<button id="grade" class="btn primary">Grade answers</button><div id="score" class="quiz-result" aria-live="polite"></div></section><section id="references"><h2>References</h2><p><a href="${DOCS[m.source]}" target="_blank" rel="noreferrer">Official ${m.source} documentation â†—</a></p><p>Related: ${m.lessons.filter(l=>l.id!==id).map(l=>`<a href="#/lesson/${l.id}">${l.title}</a>`).join(' Â· ')}</p></section><nav class="lesson-actions">${idx>0?`<a class="btn ghost" href="#/lesson/${allLessons[idx-1].id}">â† Previous</a>`:''}${idx<allLessons.length-1?`<a class="btn primary" href="#/lesson/${allLessons[idx+1].id}">Next lesson â†’</a>`:''}</nav></article><aside class="lesson-toc"><div class="side-label">On this page</div>${['objectives','concept','architecture','implementation','run','failure','tradeoffs','practice','quiz','references'].map(s=>`<a href="#${s}">${s[0].toUpperCase()+s.slice(1)}</a>`).join('')}</aside></div>`,'curriculum');$('#complete').onclick=()=>{state.completed.has(id)?state.completed.delete(id):state.completed.add(id);save();toast(state.completed.has(id)?'Lesson completed':'Completion removed');lesson(id)};$('#bookmark').onclick=()=>{state.bookmarks.has(id)?state.bookmarks.delete(id):state.bookmarks.add(id);save();toast(state.bookmarks.has(id)?'Lesson bookmarked':'Bookmark removed');lesson(id)};$('#grade').onclick=()=>gradeQuiz(m.id,q.length)}
function quizFor(m){return [
 [`What is the safest first design question for ${m.title}?`,['Which product is newest?','What invariant and failure boundary matter?','How many services can we add?'],1,'Correct: begin with the invariant, owner, and failure boundary.'],
 [`Which response best handles: â€œ${m.failure}â€`,['Add unbounded retries','Observe saturation and preserve a bounded recovery path','Ignore it until customers complain'],1,'Correct: recovery needs bounds, observability, and a preserved invariant.'],
 ['What does a timeout prove?',['The remote operation failed','The caller stopped waiting; outcome may be unknown','The network is permanently down'],1,'A timeout bounds waiting; it does not prove the remote side effect did not happen.'],
 ['Why is idempotency important?',['It removes all failures','It makes repeated attempts safe at the chosen business boundary','It guarantees global exactly-once delivery'],1,'Idempotency constrains effects; it does not create a global exactly-once guarantee.'],
 ['Which evidence best supports production readiness?',['It worked once locally','A framework calls it production-ready','Tests, telemetry, capacity evidence, recovery drills, and stated assumptions'],2,'Readiness is evidence across behavior and operations, not a label.']
];}
function quizHTML(q,i){return `<fieldset class="quiz"><legend>${i+1}. ${q[0]}</legend>${q[1].map((a,j)=>`<label><input type="radio" name="q${i}" value="${j}"> ${a}</label>`).join('')}<div class="quiz-result" id="explain-${i}"></div></fieldset>`}
function gradeQuiz(mid,n){let score=0;const q=quizFor(MODULES.find(m=>m.id===mid));q.forEach((item,i)=>{const chosen=$(`input[name=q${i}]:checked`);const ok=chosen&&Number(chosen.value)===item[2];if(ok)score++;$(`#explain-${i}`).textContent=(ok?'âœ“ ':'â†’ ')+item[3]});state.scores[mid]=score;save();$('#score').textContent=`Score: ${score}/${n}. ${score===n?'Excellentâ€”now prove it in the lab.':'Review the explanations and retry.'}`}
function lab(){layout(`<div class="eyebrow">Interactive architecture laboratory</div><h1 class="page-title">Follow the request. Break the system.</h1><p class="lede">Select a component, then toggle failure mode to see which responsibilities and recovery paths change.</p><div class="lab-grid"><div class="lab-components">${['Gateway','Order','Inventory','Payment','Event log','Notification'].map((x,i)=>`<button class="component ${i===1?'active':''}" data-component="${x}">${x}</button>`).join('')}<button id="failure-toggle" class="btn ghost">Toggle failure path</button></div><div id="lab-canvas" class="lab-canvas"><div class="topology"><div class="node sync" data-component="Gateway">Gateway<br><small>auth Â· budget</small></div><div class="node sync active" data-component="Order">Order<br><small>saga owner</small></div><div class="node sync" data-component="Inventory">Inventory<br><small>reserve stock</small></div><div class="node sync" data-component="Payment">Payment<br><small>sandbox auth</small></div><div class="node event" data-component="Event log">Event log<br><small>retained facts</small></div><div class="node event" data-component="Notification">Notification<br><small>idempotent task</small></div></div><div id="lab-detail" class="lab-detail"><h3>Order</h3><p>Owns order state and the saga decision. It never writes inventory or payment data directly.</p></div></div></div><div class="callout"><strong>Normal path</strong>Gateway â†’ Order â†’ Inventory reserve â†’ Payment authorization â†’ Order confirmed â†’ retained event â†’ notification task. Failure mode highlights the synchronous blast radius; compensation releases inventory after a failed payment.</div>`,'lab');const details={Gateway:'Authenticates, applies an end-to-end request budget, and routes. It does not own checkout state.',Order:'Owns order state and the saga decision. It never writes inventory or payment data directly.',Inventory:'Owns stock and reservations. A reservation has an expiry and idempotency key.',Payment:'Uses a safe sandbox adapter. A timeout means unknown outcome, so lookup precedes retry.', 'Event log':'Kafka retains domain facts for projections and replay; it is not the task queue.',Notification:'RabbitMQ delivers notification work. The consumer acknowledges only after a durable side effect or inbox record.'};$$('[data-component]').forEach(b=>b.onclick=()=>{$$('[data-component]').forEach(x=>x.classList.remove('active'));$$(`[data-component="${b.dataset.component}"]`).forEach(x=>x.classList.add('active'));$('#lab-detail').innerHTML=`<h3>${b.dataset.component}</h3><p>${details[b.dataset.component]}</p>`});$('#failure-toggle').onclick=()=>{$('#lab-canvas').classList.toggle('failure-on');$('#lab-detail').innerHTML=$('#lab-canvas').classList.contains('failure-on')?'<h3>Payment timeout Â· unknown outcome</h3><p>Order pauses. It queries the provider by idempotency key before retrying. If authorization failed, it issues a release-inventory compensation. The event log records the transition after the local order update through an outbox.</p>':'<h3>Normal flow restored</h3><p>Every synchronous hop consumes the shared deadline; asynchronous consumers remain independently retryable.</p>'}}
function projects(){layout(`<div class="eyebrow">Build portfolio evidence</div><h1 class="page-title">Project center</h1><p class="lede">Each project requires a design record, tests, observable failure behavior, and an honest operational-readiness statement.</p><div class="grid" style="margin-top:30px">${PROJECTS.map(projectCard).join('')}</div><section><div class="section-head"><div><div class="eyebrow">Capstone blueprint</div><h2>Production-style commerce platform</h2></div></div><div class="card"><h3>Repository map</h3>${codeBlock({label:'Reference structure',lang:'text',code:`services/{gateway,identity,catalog,inventory,cart,order,payment,notification,search}/\nplatform/{compose,kubernetes,otel,prometheus,grafana}/\ncontracts/{openapi,protobuf,events}/\ndb/{migrations,seeds}/\ntests/{contract,integration,e2e,failure}/\ndocs/{adr,runbooks,threat-model,readiness}/\n.github/workflows/ci.yml`})}<h3>Milestones</h3><ol class="criteria"><li>Contracts, invariants, ownership map and ADRs.</li><li>Identity, catalog, cart and inventory on PostgreSQL; Redis only where measured.</li><li>Order saga and payment sandbox with idempotency and compensation.</li><li>RabbitMQ for notification tasks; Kafka for retained domain events and search projection.</li><li>Outbox relay, inbox deduplication, retries, DLQs and replay tooling.</li><li>Compose environment, Kubernetes manifests, OTel Collector, Prometheus and Grafana.</li><li>CI gates, signed images, migration plan, runbooks, SLOs and failure drills.</li></ol><div class="callout"><strong>Operational boundary</strong>This reference is not production-ready merely because it runs locally. Real deployment still requires threat review, capacity tests, managed-service configuration, secret rotation, restore verification, on-call ownership, and compliance decisions.</div></div></section>`,'projects')}
function reference(){layout(`<div class="eyebrow">Glossary and primary sources</div><h1 class="page-title">Reference center</h1><div class="curriculum-toolbar"><input id="gsearch" class="search" type="search" placeholder="Search termsâ€¦" aria-label="Search glossary"></div><div id="glossary" class="grid">${GLOSSARY.map(gloss).join('')}</div><section><div class="section-head"><div><div class="eyebrow">Source index</div><h2>Official documentation</h2></div></div><div class="refs">${REFERENCES.map(r=>`<a class="ref" href="${r[1]}" target="_blank" rel="noreferrer"><strong>${r[0]} â†—</strong><small>${r[2]}</small></a>`).join('')}</div><div class="callout"><strong>Version note Â· verified 14 October 2026</strong>Examples target Go 1.27.x and portable Kubernetes 1.37 concepts. External product docs evolve; verify patch versions and compatibility before production upgrades. OpenTelemetry Go traces and metrics are stable; logs remain pre-stable.</div></section>`,'reference');$('#gsearch').oninput=e=>{const q=e.target.value.toLowerCase();$('#glossary').innerHTML=GLOSSARY.filter(x=>x.join(' ').toLowerCase().includes(q)).map(gloss).join('')||'<div class="empty">No matching terms.</div>'}}
function gloss(x){return `<article class="card"><div class="eyebrow">Definition</div><h3>${x[0]}</h3><p>${x[1]}</p></article>`}
function dashboard(){const byLevel=['Beginner','Intermediate','Advanced','Expert'].map(level=>{const ls=allLessons.filter(l=>l.module.level===level);return [level,ls.filter(l=>state.completed.has(l.id)).length,ls.length]});layout(`<div class="eyebrow">Local learning record</div><h1 class="page-title">Progress dashboard</h1><p class="lede">This progress is stored only in this browser. It is not synchronized to an account or server.</p><div class="dashboard-grid" style="margin-top:28px"><section class="card"><div class="big-progress">${pct()}%</div><h3>${state.completed.size} of ${allLessons.length} lessons complete</h3>${byLevel.map(x=>`<div class="bar-row"><span>${x[0]}</span><div class="meter"><span style="width:${x[1]/x[2]*100}%"></span></div><span>${x[1]}/${x[2]}</span></div>`).join('')}</section><section class="card"><div class="eyebrow">Assessment</div><h3>${Object.keys(state.scores).length} modules attempted</h3><p>${Object.keys(state.scores).length?`Average ${Math.round(Object.values(state.scores).reduce((a,b)=>a+b,0)/(Object.keys(state.scores).length*5)*100)}%`:'Complete a lesson quiz to see scores.'}</p></section></div><section><div class="section-head"><div><div class="eyebrow">Saved for later</div><h2>Bookmarks</h2></div></div><div class="grid">${allLessons.filter(l=>state.bookmarks.has(l.id)).map(l=>`<article class="card"><span class="badge ${l.module.level}">${l.module.level}</span><h3>${l.title}</h3><p>${l.module.title}</p><a class="card-link" href="#/lesson/${l.id}"></a></article>`).join('')||'<div class="empty">Bookmark a lesson and it will appear here.</div>'}</div></section>`,'dashboard')}
function notFound(){layout(`<div class="empty"><h1>404</h1><p>That lesson or page is outside the fieldbook.</p><a class="btn primary" href="#/">Return to overview</a></div>`,'')}
function route(){window.scrollTo(0,0);const path=location.hash.slice(1)||'/';if(path==='/')return home();if(path==='/curriculum')return curriculum();if(path==='/lab')return lab();if(path==='/projects')return projects();if(path==='/reference')return reference();if(path==='/dashboard')return dashboard();if(path.startsWith('/lesson/'))return lesson(path.split('/')[2]);notFound()}
addEventListener('hashchange',route);route();
}

